draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // Draw universal law shape
  ctx.beginPath();
  ctx.lineWidth = 5;
  ctx.arc(W/2, H/2 - 50, 30 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // Draw categorical imperative text
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Act only according to that maxim', W/2, H/2 + 100);
  ctx.fillText('whereby you can at the same time will', W/2, H/2 + 130);
  ctx.fillText('that it should become a universal law', W/2, H/2 + 160);

  ctx.restore();
}
